            break
        file_name = row["file"]
        line = int(row["line"])
        if file_name == "/candidate/verification.k" and line in LOCAL:
            disposition, reason = LOCAL[line]
        elif file_name == "/candidate/verification.k":
            disposition, reason = fixed_assessment(row["kind"], row["attributes"])
